using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Agents.AI;

// Configuration
var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this app.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

// Build the DI container
var services = new ServiceCollection();
services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var serviceProvider = services.BuildServiceProvider();
var chatClient = serviceProvider.GetRequiredService<IChatClient>();

// Define tools available to the agent
var researchTools = new ResearchTools();
var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// Create the research agent with Microsoft Agent Framework
var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        },
    },
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the SearchWeb tool to find relevant information (make 2-3 searches with different queries).
        2. Use the SaveNote tool to record key findings from each search.
        3. Use the GetNotes tool to review all your collected notes.
        4. Provide a final comprehensive summary of your research findings.

        Be thorough but concise. Focus on factual information.
        """,
    tools: tools);

// Get the research topic from args or prompt
var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of large language models on software development in 2025";

Console.WriteLine($"🔍 Researching: {topic}\n");
Console.WriteLine(new string('─', 60));

// Run the agent
var response = await agent.RunAsync(
    $"Research the following topic and provide a summary: {topic}");

Console.WriteLine("\n" + new string('─', 60));
Console.WriteLine("📋 Research Summary:\n");
Console.WriteLine(response.Text);

// Tools implementation
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    [Description("Search the web for information about a query. Returns search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use a public search API (DuckDuckGo instant answer)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await _httpClient.GetStringAsync(url);

            // Parse relevant fields from the JSON response
            var doc = System.Text.Json.JsonDocument.Parse(json);
            var results = new List<string>();

            var abstractText = doc.RootElement.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            var abstractSource = doc.RootElement.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractSource))
                results.Add($"Source: {abstractSource}");

            if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                        results.Add($"- {text.GetString()}");
                }
            }

            if (results.Count == 0)
                return $"No detailed results found for '{query}'. Try a different search query.";

            return string.Join("\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("The note content to save")] string content,
        [Description("A short label for this note")] string label)
    {
        _notes.Add($"[{label}] {content}");
        Console.WriteLine($"  📝 Note saved: {label}");
        return $"Note saved: '{label}' ({content.Length} chars)";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📖 Retrieved {_notes.Count} notes");
        return string.Join("\n\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

