 // Tools implementation
 sealed class ResearchTools
 {
     private readonly List<string> _notes = [];
     private readonly HttpClient _httpClient = new();

     [Description("Search the web for information about a query. Returns search result snippets.")]
     public async Task<string> SearchWeb(
         [Description("The search query to look up")] string query)
     {
         Console.WriteLine($"  🌐 Searching: \"{query}\"");

         try
         {
             // Use DuckDuckGo instant answer API (no key required)
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var json = await _httpClient.GetStringAsync(url);

             var doc = System.Text.Json.JsonDocument.Parse(json);
             var results = new List<string>();

             var abstractText = doc.RootElement.GetProperty("AbstractText").GetString();
             if (!string.IsNullOrWhiteSpace(abstractText))
                 results.Add($"Summary: {abstractText}");

             var abstractSource = doc.RootElement.GetProperty("AbstractSource").GetString();
             if (!string.IsNullOrWhiteSpace(abstractSource))
                 results.Add($"Source: {abstractSource}");

             if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
             {
                 foreach (var relatedTopic in topics.EnumerateArray().Take(5))
                 {
                     if (relatedTopic.TryGetProperty("Text", out var text))
                         results.Add($"- {text.GetString()}");
                 }
             }

             if (results.Count == 0)
                 return $"No detailed results found for '{query}'. Try a different search query.";

             return string.Join("\n", results);
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     }

     [Description("Save a research note. Use this to record key findings during research.")]
     public string SaveNote(
         [Description("The note content to save")] string content,
         [Description("A short label for this note")] string label)
     {
         _notes.Add($"[{label}] {content}");
         Console.WriteLine($"  📝 Note saved: {label}");
         return $"Note saved: '{label}' ({content.Length} chars)";
     }

     [Description("Retrieve all saved research notes.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         Console.WriteLine($"  📖 Retrieved {_notes.Count} notes");
         return string.Join("\n\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
     }
 }
